INSERT INTO cm_blocks
  (block_id, doc_id, parent_block_id, block_type, seq_order, depth, content_text, attrs_json, annotations_json, meta_json)
VALUES
 ('BLK:said-discourse-01','CM:01KSEEDWVSAIDDISCOURSE00001',NULL,'heading',0,0,'The core thesis','{"level":2}','[{"type":"text","text":"The core thesis"}]','{}'),
 ('BLK:said-discourse-02','CM:01KSEEDWVSAIDDISCOURSE00001',NULL,'paragraph',1,0,'Orientalism is, in Said’s definition, a Western style of thought and a "corporate institution for dealing with the Orient — dealing with it by making statements about it, authorizing views of it, describing it, by teaching it, settling it, ruling over it." It is less a body of truths about the East than a structure of power-knowledge through which Europe produced and managed "the Orient" politically, sociologically, militarily, ideologically, scientifically, and imaginatively.','{}','[{"type":"text","text":"Orientalism is, in Said’s definition, a Western style of thought and a \"corporate institution for dealing with the Orient — dealing with it by making statements about it, authorizing views of it, describing it, by teaching it, settling it, ruling over it.\" It is less a body of truths about the East than a structure of power-knowledge through which Europe produced and managed \"the Orient\" politically, sociologically, militarily, ideologically, scientifically, and imaginatively."}]','{}'),
 ('BLK:said-discourse-03','CM:01KSEEDWVSAIDDISCOURSE00001',NULL,'heading',2,0,'Three senses of Orientalism','{"level":2}','[{"type":"text","text":"Three senses of Orientalism"}]','{}'),
 ('BLK:said-discourse-04','CM:01KSEEDWVSAIDDISCOURSE00001',NULL,'bulletList',3,0,NULL,'{}','[]','{}'),
 ('BLK:said-discourse-05','CM:01KSEEDWVSAIDDISCOURSE00001','BLK:said-discourse-04','listItem',0,1,NULL,'{}','[]','{}'),
 ('BLK:said-discourse-06','CM:01KSEEDWVSAIDDISCOURSE00001','BLK:said-discourse-05','paragraph',0,2,'Academic: anyone who teaches, writes about, or researches the Orient — the scholarly disciplines, chairs, learned societies, and journals.','{}','[{"type":"text","text":"Academic: anyone who teaches, writes about, or researches the Orient — the scholarly disciplines, chairs, learned societies, and journals."}]','{}'),
 ('BLK:said-discourse-07','CM:01KSEEDWVSAIDDISCOURSE00001','BLK:said-discourse-04','listItem',1,1,NULL,'{}','[]','{}'),
 ('BLK:said-discourse-08','CM:01KSEEDWVSAIDDISCOURSE00001','BLK:said-discourse-07','paragraph',0,2,'Imaginative: a style of thought based on an ontological and epistemological distinction between "the Orient" and "the Occident."','{}','[{"type":"text","text":"Imaginative: a style of thought based on an ontological and epistemological distinction between \"the Orient\" and \"the Occident.\""}]','{}'),
 ('BLK:said-discourse-09','CM:01KSEEDWVSAIDDISCOURSE00001','BLK:said-discourse-04','listItem',2,1,NULL,'{}','[]','{}'),
 ('BLK:said-discourse-10','CM:01KSEEDWVSAIDDISCOURSE00001','BLK:said-discourse-09','paragraph',0,2,'Institutional/corporate: from the late eighteenth century, a corporate institution for dominating, restructuring, and having authority over the Orient.','{}','[{"type":"text","text":"Institutional/corporate: from the late eighteenth century, a corporate institution for dominating, restructuring, and having authority over the Orient."}]','{}'),
 ('BLK:said-discourse-11','CM:01KSEEDWVSAIDDISCOURSE00001',NULL,'heading',4,0,'Foucault and Gramsci','{"level":2}','[{"type":"text","text":"Foucault and Gramsci"}]','{}'),
 ('BLK:said-discourse-12','CM:01KSEEDWVSAIDDISCOURSE00001',NULL,'paragraph',5,0,'Said adapts Foucault’s notion of discourse to argue that without examining Orientalism as a discourse "one cannot possibly understand the enormously systematic discipline by which European culture was able to manage — and even produce — the Orient." From Gramsci he takes cultural hegemony: Orientalism’s durability comes from a hegemonic consent that makes Western superiority feel self-evident.','{}','[{"type":"text","text":"Said adapts Foucault’s notion of discourse to argue that without examining Orientalism as a discourse \"one cannot possibly understand the enormously systematic discipline by which European culture was able to manage — and even produce — the Orient.\" From Gramsci he takes cultural hegemony: Orientalism’s durability comes from a hegemonic consent that makes Western superiority feel self-evident."}]','{}'),
 ('BLK:said-discourse-13','CM:01KSEEDWVSAIDDISCOURSE00001',NULL,'blockquote',6,0,NULL,'{}','[]','{}'),
 ('BLK:said-discourse-14','CM:01KSEEDWVSAIDDISCOURSE00001','BLK:said-discourse-13','paragraph',0,1,'Orientalism is never far from … the idea of Europe, a collective notion identifying "us" Europeans against all "those" non-Europeans.','{}','[{"type":"text","text":"Orientalism is never far from … the idea of Europe, a collective notion identifying \"us\" Europeans against all \"those\" non-Europeans."}]','{}'),
 ('BLK:said-discourse-15','CM:01KSEEDWVSAIDDISCOURSE00001',NULL,'paragraph',7,0,'Crucially, Orientalism is productive, not merely descriptive: it is a distribution of geopolitical awareness into texts that brought the very object it claimed to study into being.','{}','[{"type":"text","text":"Crucially, Orientalism is productive, not merely descriptive: it is a distribution of geopolitical awareness into texts that brought the very object it claimed to study into being."}]','{}');
INSERT INTO cm_blocks
  (block_id, doc_id, parent_block_id, block_type, seq_order, depth, content_text, attrs_json, annotations_json, meta_json)
VALUES
 ('BLK:said-geography-01','CM:01KSEEDWVSAIDGEOGRAPHY0002',NULL,'heading',0,0,'Inventing the Orient','{"level":2}','[{"type":"text","text":"Inventing the Orient"}]','{}'),
 ('BLK:said-geography-02','CM:01KSEEDWVSAIDGEOGRAPHY0002',NULL,'paragraph',1,0,'The Orient is "not an inert fact of nature" but "an idea that has a history and a tradition of thought, imagery, and vocabulary that have given it reality and presence in and for the West." Geography here is imaginative: cultures draw a line between a familiar space ("ours") and an unfamiliar space beyond ("theirs"), and the distinction is arbitrary — it does not require the "barbarians" on the far side to acknowledge it.','{}','[{"type":"text","text":"The Orient is \"not an inert fact of nature\" but \"an idea that has a history and a tradition of thought, imagery, and vocabulary that have given it reality and presence in and for the West.\" Geography here is imaginative: cultures draw a line between a familiar space (\"ours\") and an unfamiliar space beyond (\"theirs\"), and the distinction is arbitrary — it does not require the \"barbarians\" on the far side to acknowledge it."}]','{}'),
 ('BLK:said-geography-03','CM:01KSEEDWVSAIDGEOGRAPHY0002',NULL,'heading',2,0,'Orient vs Occident','{"level":2}','[{"type":"text","text":"Orient vs Occident"}]','{}'),
 ('BLK:said-geography-04','CM:01KSEEDWVSAIDGEOGRAPHY0002',NULL,'bulletList',3,0,NULL,'{}','[]','{}'),
 ('BLK:said-geography-05','CM:01KSEEDWVSAIDGEOGRAPHY0002','BLK:said-geography-04','listItem',0,1,NULL,'{}','[]','{}'),
 ('BLK:said-geography-06','CM:01KSEEDWVSAIDGEOGRAPHY0002','BLK:said-geography-05','paragraph',0,2,'The division is ontological and epistemological: East and West are treated as stable, opposed essences.','{}','[{"type":"text","text":"The division is ontological and epistemological: East and West are treated as stable, opposed essences."}]','{}'),
 ('BLK:said-geography-07','CM:01KSEEDWVSAIDGEOGRAPHY0002','BLK:said-geography-04','listItem',1,1,NULL,'{}','[]','{}'),
 ('BLK:said-geography-08','CM:01KSEEDWVSAIDGEOGRAPHY0002','BLK:said-geography-07','paragraph',0,2,'The Orient is defined by lack and difference — the contrasting Other against which the Occident defines itself.','{}','[{"type":"text","text":"The Orient is defined by lack and difference — the contrasting Other against which the Occident defines itself."}]','{}'),
 ('BLK:said-geography-09','CM:01KSEEDWVSAIDGEOGRAPHY0002','BLK:said-geography-04','listItem',2,1,NULL,'{}','[]','{}'),
 ('BLK:said-geography-10','CM:01KSEEDWVSAIDGEOGRAPHY0002','BLK:said-geography-09','paragraph',0,2,'Distance becomes hierarchy: the East is rendered past, static, feminine, and irrational; the West present, dynamic, masculine, and rational.','{}','[{"type":"text","text":"Distance becomes hierarchy: the East is rendered past, static, feminine, and irrational; the West present, dynamic, masculine, and rational."}]','{}'),
 ('BLK:said-geography-11','CM:01KSEEDWVSAIDGEOGRAPHY0002',NULL,'heading',4,0,'The theatrical stage','{"level":2}','[{"type":"text","text":"The theatrical stage"}]','{}'),
 ('BLK:said-geography-12','CM:01KSEEDWVSAIDGEOGRAPHY0002',NULL,'paragraph',5,0,'Said likens Orientalist representation to "a theatrical stage affixed to Europe" on which the whole East is made to appear. Figures and places become types and tableaux; empirical experience matters little because the Oriental is always assigned a fixed schematic place.','{}','[{"type":"text","text":"Said likens Orientalist representation to \"a theatrical stage affixed to Europe\" on which the whole East is made to appear. Figures and places become types and tableaux; empirical experience matters little because the Oriental is always assigned a fixed schematic place."}]','{}'),
 ('BLK:said-geography-13','CM:01KSEEDWVSAIDGEOGRAPHY0002',NULL,'blockquote',6,0,NULL,'{}','[]','{}'),
 ('BLK:said-geography-14','CM:01KSEEDWVSAIDGEOGRAPHY0002','BLK:said-geography-13','paragraph',0,1,'The Orient was almost a European invention, and had been since antiquity a place of romance, exotic beings, haunting memories and landscapes, remarkable experiences.','{}','[{"type":"text","text":"The Orient was almost a European invention, and had been since antiquity a place of romance, exotic beings, haunting memories and landscapes, remarkable experiences."}]','{}');
INSERT INTO cm_blocks
  (block_id, doc_id, parent_block_id, block_type, seq_order, depth, content_text, attrs_json, annotations_json, meta_json)
VALUES
 ('BLK:said-latent-01','CM:01KSEEDWVSAIDLATENT0000003',NULL,'heading',0,0,'Two levels of one discourse','{"level":2}','[{"type":"text","text":"Two levels of one discourse"}]','{}'),
 ('BLK:said-latent-02','CM:01KSEEDWVSAIDLATENT0000003',NULL,'paragraph',1,0,'Said distinguishes latent Orientalism — an almost unconscious, deep, and remarkably stable set of certainties about the Orient — from manifest Orientalism, the stated views and the changing content of what is actually said and written about Oriental societies, languages, and peoples.','{}','[{"type":"text","text":"Said distinguishes latent Orientalism — an almost unconscious, deep, and remarkably stable set of certainties about the Orient — from manifest Orientalism, the stated views and the changing content of what is actually said and written about Oriental societies, languages, and peoples."}]','{}'),
 ('BLK:said-latent-03','CM:01KSEEDWVSAIDLATENT0000003',NULL,'bulletList',2,0,NULL,'{}','[]','{}'),
 ('BLK:said-latent-04','CM:01KSEEDWVSAIDLATENT0000003','BLK:said-latent-03','listItem',0,1,NULL,'{}','[]','{}'),
 ('BLK:said-latent-05','CM:01KSEEDWVSAIDLATENT0000003','BLK:said-latent-04','paragraph',0,2,'Latent: the unanimous, durable, unconscious substrate — the Orient as fixed, backward, silent, sensual, despotic, and incapable of self-government.','{}','[{"type":"text","text":"Latent: the unanimous, durable, unconscious substrate — the Orient as fixed, backward, silent, sensual, despotic, and incapable of self-government."}]','{}'),
 ('BLK:said-latent-06','CM:01KSEEDWVSAIDLATENT0000003','BLK:said-latent-03','listItem',1,1,NULL,'{}','[]','{}'),
 ('BLK:said-latent-07','CM:01KSEEDWVSAIDLATENT0000003','BLK:said-latent-06','paragraph',0,2,'Manifest: the explicit knowledge that changes with each writer and era, yet always rests on the same latent base.','{}','[{"type":"text","text":"Manifest: the explicit knowledge that changes with each writer and era, yet always rests on the same latent base."}]','{}'),
 ('BLK:said-latent-08','CM:01KSEEDWVSAIDLATENT0000003',NULL,'paragraph',3,0,'Differences among Orientalist authors are differences in manifest form only; the latent content remains constant. This is why even sympathetic or learned writers reproduce the same essential structure.','{}','[{"type":"text","text":"Differences among Orientalist authors are differences in manifest form only; the latent content remains constant. This is why even sympathetic or learned writers reproduce the same essential structure."}]','{}'),
 ('BLK:said-latent-09','CM:01KSEEDWVSAIDLATENT0000003',NULL,'heading',4,0,'Stability and transmission','{"level":2}','[{"type":"text","text":"Stability and transmission"}]','{}'),
 ('BLK:said-latent-10','CM:01KSEEDWVSAIDLATENT0000003',NULL,'paragraph',5,0,'Latent Orientalism is transmitted across generations like a family of ideas; it has the coherence and the slow rate of change of an unconscious. Its near-uniformity is what gives Orientalism its authority and its capacity to survive empirical contradiction.','{}','[{"type":"text","text":"Latent Orientalism is transmitted across generations like a family of ideas; it has the coherence and the slow rate of change of an unconscious. Its near-uniformity is what gives Orientalism its authority and its capacity to survive empirical contradiction."}]','{}'),
 ('BLK:said-latent-11','CM:01KSEEDWVSAIDLATENT0000003',NULL,'blockquote',6,0,NULL,'{}','[]','{}'),
 ('BLK:said-latent-12','CM:01KSEEDWVSAIDLATENT0000003','BLK:said-latent-11','paragraph',0,1,'Latent Orientalism also encouraged a peculiarly … male conception of the world.','{}','[{"type":"text","text":"Latent Orientalism also encouraged a peculiarly … male conception of the world."}]','{}');
INSERT INTO cm_blocks
  (block_id, doc_id, parent_block_id, block_type, seq_order, depth, content_text, attrs_json, annotations_json, meta_json)
VALUES
 ('BLK:said-knowpower-01','CM:01KSEEDWVSAIDKNOWPOWER004',NULL,'heading',0,0,'To know is to dominate','{"level":2}','[{"type":"text","text":"To know is to dominate"}]','{}'),
 ('BLK:said-knowpower-02','CM:01KSEEDWVSAIDKNOWPOWER004',NULL,'paragraph',1,0,'For Said, knowledge of the Orient and power over it are inseparable. He reads Arthur Balfour’s 1910 Commons speech and Lord Cromer’s writings on Egypt as exhibits: England knows Egypt, and "Egypt is what England knows." To know the Oriental is to have authority over him; the claim of expertise legitimizes the claim of rule.','{}','[{"type":"text","text":"For Said, knowledge of the Orient and power over it are inseparable. He reads Arthur Balfour’s 1910 Commons speech and Lord Cromer’s writings on Egypt as exhibits: England knows Egypt, and \"Egypt is what England knows.\" To know the Oriental is to have authority over him; the claim of expertise legitimizes the claim of rule."}]','{}'),
 ('BLK:said-knowpower-03','CM:01KSEEDWVSAIDKNOWPOWER004',NULL,'blockquote',2,0,NULL,'{}','[]','{}'),
 ('BLK:said-knowpower-04','CM:01KSEEDWVSAIDKNOWPOWER004','BLK:said-knowpower-03','paragraph',0,1,'Knowledge of subject races or Orientals is what makes their management easy and profitable; knowledge gives power, more power requires more knowledge.','{}','[{"type":"text","text":"Knowledge of subject races or Orientals is what makes their management easy and profitable; knowledge gives power, more power requires more knowledge."}]','{}'),
 ('BLK:said-knowpower-05','CM:01KSEEDWVSAIDKNOWPOWER004',NULL,'heading',3,0,'From scholarship to administration','{"level":2}','[{"type":"text","text":"From scholarship to administration"}]','{}'),
 ('BLK:said-knowpower-06','CM:01KSEEDWVSAIDKNOWPOWER004',NULL,'bulletList',4,0,NULL,'{}','[]','{}'),
 ('BLK:said-knowpower-07','CM:01KSEEDWVSAIDKNOWPOWER004','BLK:said-knowpower-06','listItem',0,1,NULL,'{}','[]','{}'),
 ('BLK:said-knowpower-08','CM:01KSEEDWVSAIDKNOWPOWER004','BLK:said-knowpower-07','paragraph',0,2,'Philology, history, and travel writing supplied the categories that colonial administration then put to work.','{}','[{"type":"text","text":"Philology, history, and travel writing supplied the categories that colonial administration then put to work."}]','{}'),
 ('BLK:said-knowpower-09','CM:01KSEEDWVSAIDKNOWPOWER004','BLK:said-knowpower-06','listItem',1,1,NULL,'{}','[]','{}'),
 ('BLK:said-knowpower-10','CM:01KSEEDWVSAIDKNOWPOWER004','BLK:said-knowpower-09','paragraph',0,2,'The Orientalist becomes the indispensable mediator who renders a "raw" Orient intelligible to Europe.','{}','[{"type":"text","text":"The Orientalist becomes the indispensable mediator who renders a \"raw\" Orient intelligible to Europe."}]','{}'),
 ('BLK:said-knowpower-11','CM:01KSEEDWVSAIDKNOWPOWER004','BLK:said-knowpower-06','listItem',2,1,NULL,'{}','[]','{}'),
 ('BLK:said-knowpower-12','CM:01KSEEDWVSAIDKNOWPOWER004','BLK:said-knowpower-11','paragraph',0,2,'The Oriental is represented as a subject to be studied, classified, and governed — never an interlocutor.','{}','[{"type":"text","text":"The Oriental is represented as a subject to be studied, classified, and governed — never an interlocutor."}]','{}'),
 ('BLK:said-knowpower-13','CM:01KSEEDWVSAIDKNOWPOWER004',NULL,'paragraph',5,0,'Napoleon’s 1798 expedition and the resulting Description de l’Égypte are Said’s model of "a truly scientific appropriation of one culture by another": the project to know Egypt was simultaneously the project to possess it.','{}','[{"type":"text","text":"Napoleon’s 1798 expedition and the resulting Description de l’Égypte are Said’s model of \"a truly scientific appropriation of one culture by another\": the project to know Egypt was simultaneously the project to possess it."}]','{}');
INSERT INTO cm_blocks
  (block_id, doc_id, parent_block_id, block_type, seq_order, depth, content_text, attrs_json, annotations_json, meta_json)
VALUES
 ('BLK:said-repother-01','CM:01KSEEDWVSAIDREPOTHER0005',NULL,'heading',0,0,'Spoken for, never speaking','{"level":2}','[{"type":"text","text":"Spoken for, never speaking"}]','{}'),
 ('BLK:said-repother-02','CM:01KSEEDWVSAIDREPOTHER0005',NULL,'paragraph',1,0,'A defining feature of Orientalism is that the Orient is represented rather than representing itself. The Oriental is made an object of European discourse — described, classified, and contained — while being denied the position of a speaking subject. Said takes as an epigraph Marx’s line: "They cannot represent themselves; they must be represented."','{}','[{"type":"text","text":"A defining feature of Orientalism is that the Orient is represented rather than representing itself. The Oriental is made an object of European discourse — described, classified, and contained — while being denied the position of a speaking subject. Said takes as an epigraph Marx’s line: \"They cannot represent themselves; they must be represented.\""}]','{}'),
 ('BLK:said-repother-03','CM:01KSEEDWVSAIDREPOTHER0005',NULL,'heading',2,0,'Representation, not reality','{"level":2}','[{"type":"text","text":"Representation, not reality"}]','{}'),
 ('BLK:said-repother-04','CM:01KSEEDWVSAIDREPOTHER0005',NULL,'bulletList',3,0,NULL,'{}','[]','{}'),
 ('BLK:said-repother-05','CM:01KSEEDWVSAIDREPOTHER0005','BLK:said-repother-04','listItem',0,1,NULL,'{}','[]','{}'),
 ('BLK:said-repother-06','CM:01KSEEDWVSAIDREPOTHER0005','BLK:said-repother-05','paragraph',0,2,'Orientalist texts refer chiefly to other Orientalist texts, forming a self-confirming "citationary" tradition.','{}','[{"type":"text","text":"Orientalist texts refer chiefly to other Orientalist texts, forming a self-confirming \"citationary\" tradition."}]','{}'),
 ('BLK:said-repother-07','CM:01KSEEDWVSAIDREPOTHER0005','BLK:said-repother-04','listItem',1,1,NULL,'{}','[]','{}'),
 ('BLK:said-repother-08','CM:01KSEEDWVSAIDREPOTHER0005','BLK:said-repother-07','paragraph',0,2,'Representations are valued for internal consistency and authority, not for fidelity to living societies.','{}','[{"type":"text","text":"Representations are valued for internal consistency and authority, not for fidelity to living societies."}]','{}'),
 ('BLK:said-repother-09','CM:01KSEEDWVSAIDREPOTHER0005','BLK:said-repother-04','listItem',2,1,NULL,'{}','[]','{}'),
 ('BLK:said-repother-10','CM:01KSEEDWVSAIDREPOTHER0005','BLK:said-repother-09','paragraph',0,2,'The textual attitude — the assumption that books can replace direct, reciprocal encounter — screens off the "real" Orient.','{}','[{"type":"text","text":"The textual attitude — the assumption that books can replace direct, reciprocal encounter — screens off the \"real\" Orient."}]','{}'),
 ('BLK:said-repother-11','CM:01KSEEDWVSAIDREPOTHER0005',NULL,'paragraph',4,0,'Because the Orient cannot answer back within the discourse, Orientalism functions as a closed system in which the European writer is present as a judging, surveying consciousness and the Oriental is a passive, silent presence.','{}','[{"type":"text","text":"Because the Orient cannot answer back within the discourse, Orientalism functions as a closed system in which the European writer is present as a judging, surveying consciousness and the Oriental is a passive, silent presence."}]','{}'),
 ('BLK:said-repother-12','CM:01KSEEDWVSAIDREPOTHER0005',NULL,'blockquote',5,0,NULL,'{}','[]','{}'),
 ('BLK:said-repother-13','CM:01KSEEDWVSAIDREPOTHER0005','BLK:said-repother-12','paragraph',0,1,'The Orient is watched … The European, whose sensibility tours the Orient, is a watcher, never involved, always detached.','{}','[{"type":"text","text":"The Orient is watched … The European, whose sensibility tours the Orient, is a watcher, never involved, always detached."}]','{}');
